<script setup>
import {computed,ref} from 'vue';import Navbar from './components/Navbar.vue';import Sidebar from './components/Sidebar.vue';import Toast from './components/Toast.vue';import Dashboard from './pages/Dashboard.vue';import Jobs from './pages/Jobs.vue';import MasterJobs from './pages/MasterJobs.vue';import Reports from './pages/Reports.vue';import Settings from './pages/Settings.vue';import Login from './pages/Login.vue';
const KEY='agfj-techpoint-v1',page=ref('dashboard'),mobile=ref(false),toast=ref({show:false,message:''}),logged=ref(localStorage.getItem('agfj_logged_in')==='1');
const demo={profile:{name:'Teknisi Demo',code:'TECH-001',team:'Tim Lapangan'},target:1000,jobs:[{id:1,date:'2026-09-01',typeId:1,qty:2},{id:2,date:'2026-09-02',typeId:2,qty:4},{id:3,date:'2026-09-04',typeId:3,qty:3},{id:4,date:'2026-09-07',typeId:1,qty:2},{id:5,date:'2026-09-10',typeId:4,qty:5},{id:6,date:'2026-09-12',typeId:2,qty:3},{id:7,date:'2026-09-15',typeId:3,qty:2}],masterJobs:[{id:1,code:'PB01',name:'Pasang Baru',points:10,active:true},{id:2,code:'GS01',name:'Gangguan',points:5,active:true},{id:3,code:'UP01',name:'Upgrade',points:7,active:true},{id:4,code:'MT01',name:'Maintenance',points:8,active:true}]};
function load(){try{return JSON.parse(localStorage.getItem(KEY))||structuredClone(demo)}catch{return structuredClone(demo)}}const state=ref(load());function save(){localStorage.setItem(KEY,JSON.stringify(state.value))}
const masters=computed(()=>state.value.masterJobs.filter(x=>x.active));const jobs=computed(()=>state.value.jobs.map(x=>{const m=state.value.masterJobs.find(y=>y.id===x.typeId);return {...x,master:m,points:m?.points||0,total:(m?.points||0)*x.qty}}).sort((a,b)=>b.date.localeCompare(a.date)));const total=computed(()=>jobs.value.reduce((s,x)=>s+x.total,0));const qty=computed(()=>jobs.value.reduce((s,x)=>s+Number(x.qty),0));const pct=computed(()=>state.value.target?Math.min(total.value/state.value.target*100,100):0);const rem=computed(()=>Math.max(state.value.target-total.value,0));
function nav(x){page.value=x;mobile.value=false;scrollTo({top:0,behavior:'smooth'})}function note(m){toast.value={show:true,message:m};setTimeout(()=>toast.value.show=false,2500)}function addJob(x){state.value.jobs.push({id:Date.now(),...x});save();note('Pekerjaan berhasil ditambahkan.');nav('jobs')}function removeJob(id){state.value.jobs=state.value.jobs.filter(x=>x.id!==id);save();note('Pekerjaan dihapus.')}function saveMaster(x){const i=state.value.masterJobs.findIndex(y=>y.id===x.id);if(i>=0)state.value.masterJobs[i]=x;else state.value.masterJobs.push({...x,id:Date.now()});save();note('Master pekerjaan disimpan.')}function delMaster(id){if(state.value.jobs.some(x=>x.typeId===id))return note('Jenis pekerjaan masih dipakai pada riwayat.');state.value.masterJobs=state.value.masterJobs.filter(x=>x.id!==id);save();note('Master pekerjaan dihapus.')}function settings(x){state.value.target=Number(x.target)||0;state.value.profile={...state.value.profile,...x.profile};save();note('Pengaturan tersimpan.')}function reset(){state.value=structuredClone(demo);save();note('Data demo direset.')}function login(){localStorage.setItem('agfj_logged_in','1');logged.value=true}function logout(){localStorage.removeItem('agfj_logged_in');logged.value=false}
</script>
<template><Login v-if="!logged" @login="login"/><div v-else class="app-shell"><Sidebar :active-page="page" :mobile-open="mobile" @navigate="nav" @logout="logout"/><div class="main-area"><Navbar :profile="state.profile" @toggle-menu="mobile=!mobile" @logout="logout"/><main class="page-container"><Dashboard v-if="page==='dashboard'" :total-points="total" :target="state.target" :achievement="pct" :remaining="rem" :total-qty="qty" :jobs="jobs"/><Jobs v-else-if="page==='jobs'" :jobs="jobs" :master-jobs="masters" @add-job="addJob" @remove-job="removeJob"/><MasterJobs v-else-if="page==='master'" :master-jobs="state.masterJobs" @save="saveMaster" @delete="delMaster"/><Reports v-else-if="page==='reports'" :jobs="jobs" :target="state.target" :total-points="total"/><Settings v-else :profile="state.profile" :target="state.target" @save="settings" @reset="reset"/></main></div><Toast :show="toast.show" :message="toast.message"/></div></template>